const authRes = $input.first().json;
const user = authRes.user;
const bin = $('Auth - Extract Credentials').first().binary || {};
const prevJson = $('Auth - Extract Credentials').first().json;

function parseSize(s) {
  if (typeof s === 'number') return s;
  if (!s) return 0;
  const str = String(s).trim();
  const m = str.match(/^([0-9.]+)\s*([a-zA-Z]*)$/);
  if (!m) return parseInt(str.replace(/[^0-9]/g, ''), 10) || 0;
  const num = parseFloat(m[1]);
  const unit = m[2].toUpperCase();
  if (unit === 'GB' || unit === 'GIB') return Math.round(num * 1024 * 1024 * 1024);
  if (unit === 'MB' || unit === 'MIB') return Math.round(num * 1024 * 1024);
  if (unit === 'KB' || unit === 'KIB') return Math.round(num * 1024);
  return Math.round(num);
}

function checkFileSignature(base64Data, ext) {
  // STRICT FAIL-CLOSED: Reject missing, empty, or non-string base64 data
  if (!base64Data || typeof base64Data !== 'string') return false;
  try {
    const cleanB64 = base64Data.trim();
    if (cleanB64.length < 8) return false;
    const headBuf = Buffer.from(cleanB64.slice(0, 128), 'base64');
    if (headBuf.length < 4) return false;
    const hex = headBuf.toString('hex').toLowerCase();

    switch (ext) {
      case 'pdf':
        // %PDF- (25504446)
        return hex.startsWith('25504446');
      case 'png':
        // \x89PNG\r\n\x1a\n (89504e470d0a1a0a)
        return hex.startsWith('89504e470d0a1a0a') || hex.startsWith('89504e47');
      case 'jpg':
      case 'jpeg':
        // \xFF\xD8\xFF (ffd8ff)
        return hex.startsWith('ffd8ff');
      case 'webp': {
        // RIFF (52494646) at offset 0, WEBP (57454250) at offset 8
        if (headBuf.length < 12) return false;
        const r = headBuf.slice(0, 4).toString('hex').toLowerCase();
        const w = headBuf.slice(8, 12).toString('hex').toLowerCase();
        return r === '52494646' && w === '57454250';
      }
      case 'docx':
      case 'xlsx': {
        // PK\x03\x04 (504b0304) Zip header (must be at least 30 bytes for valid local file header)
        if (headBuf.length < 30) return false;
        return hex.startsWith('504b0304');
      }
      case 'txt':
      case 'csv':
        // Plain text: non-empty, and no null bytes in header
        return headBuf.length > 0 && !headBuf.includes(0x00);
      default:
        // Unknown extension -> FAIL-CLOSED
        return false;
    }
  } catch (e) {
    // FAIL-CLOSED: Reject on any exception
    return false;
  }
}

const keys = Object.keys(bin);
if (keys.length === 0) {
  return [{
    json: {
      valid_files: false,
      error: 'Vui lòng chọn ít nhất 1 tệp hồ sơ đính kèm (PDF, ảnh scan, Word, Excel).',
      status_code: 400
    }
  }];
}

const allowedExts = ['pdf', 'png', 'jpg', 'jpeg', 'webp', 'tiff', 'docx', 'xlsx', 'txt'];
const maxFileSize = 25 * 1024 * 1024; // Official SOTRANS Standard: 25 MB

const validatedFiles = [];
for (const k of keys) {
  const b = bin[k];
  const fileName = b.fileName || 'file.pdf';
  const ext = (fileName.split('.').pop() || '').toLowerCase();

  if (!allowedExts.includes(ext)) {
    return [{
      json: {
        valid_files: false,
        error: 'Định dạng tệp "' + fileName + '" (.' + ext + ') không được hỗ trợ. Vui lòng tải lên PDF hoặc ảnh scan hợp lệ.',
        status_code: 400
      }
    }];
  }

  // File signature / magic bytes verification (Strict Fail-Closed)
  if (!b.data || String(b.data).trim().length === 0) {
    return [{
      json: {
        valid_files: false,
        error: 'Tệp "' + fileName + '" không có dữ liệu nội dung hợp lệ.',
        status_code: 400
      }
    }];
  }

  const isSigValid = checkFileSignature(b.data, ext);
  if (!isSigValid) {
    return [{
      json: {
        valid_files: false,
        error: 'Chữ ký nhị phân (File Signature) của tệp "' + fileName + '" không khớp với định dạng .' + ext + ' hoặc tệp bị hỏng.',
        status_code: 400
      }
    }];
  }

  let actualSize = parseSize(b.fileSize);
  if (!actualSize && b.data && !String(b.data).startsWith('filesystem-')) {
    actualSize = Math.round(b.data.length * 3 / 4);
  }

  if (actualSize > maxFileSize) {
    return [{
      json: {
        valid_files: false,
        error: 'Dung lượng tệp "' + fileName + '" (' + (actualSize / 1024 / 1024).toFixed(1) + 'MB) vượt quá giới hạn tối đa 25MB.',
        status_code: 400
      }
    }];
  }

  validatedFiles.push({
    binaryKey: k,
    fileName,
    ext,
    mimeType: b.mimeType || 'application/pdf',
    approxSize: actualSize
  });
}

return [{
  json: {
    valid_files: true,
    user,
    batch_id: prevJson.batch_id,
    correlation_id: prevJson.correlation_id,
    idempotency_key: prevJson.idempotency_key,
    conversation_id: prevJson.conversation_id,
    company_id: prevJson.company_id || user.company_id,
    validated_files: validatedFiles
  },
  binary: bin
}];

const fs = require('fs');
const crypto = require('crypto');

const item = $input.first().json;
const bin = $input.first().binary || {};
const user = item.user;
const batchId = item.batch_id || crypto.randomUUID();

const stagingDir = '/home/node/.n8n-files/staging';
if (!fs.existsSync(stagingDir)) {
  try { fs.mkdirSync(stagingDir, { recursive: true }); } catch(e) {}
}

const fileItems = [];
const validatedFiles = item.validated_files || [];

for (let i = 0; i < validatedFiles.length; i++) {
  const vf = validatedFiles[i];
  const b = bin[vf.binaryKey];
  if (!b) continue;

  const cleanBase = (vf.fileName || 'document.pdf').replace(/[^a-zA-Z0-9._-]/g, '_');
  const safeFileName = batchId + '_' + cleanBase;
  const diskPath = stagingDir + '/' + safeFileName;

  let fileBuf = null;
  if (this.helpers && typeof this.helpers.getBinaryDataBuffer === 'function') {
    try {
      fileBuf = await this.helpers.getBinaryDataBuffer(0, vf.binaryKey);
    } catch (hErr) {
      console.warn('getBinaryDataBuffer fallback:', hErr.message);
    }
  }

  if (!fileBuf && b.data && !String(b.data).startsWith('filesystem-')) {
    try {
      fileBuf = Buffer.from(b.data, 'base64');
    } catch(e) {}
  }

  if (fileBuf) {
    try {
      fs.writeFileSync(diskPath, fileBuf);
    } catch (saveErr) {
      console.warn('Không thể lưu file staging:', saveErr.message);
    }
  }

  const base64Str = fileBuf ? fileBuf.toString('base64') : (b.data && !String(b.data).startsWith('filesystem-') ? b.data : '');

  fileItems.push({
    fileIndex: i,
    binaryKey: vf.binaryKey,
    fileName: vf.fileName,
    mimeType: vf.mimeType || b.mimeType || 'application/pdf',
    fileSize: fileBuf ? fileBuf.length : (vf.approxSize || 0),
    fileStoragePath: '/app/chat-files/staging/' + safeFileName,
    base64Data: base64Str
  });
}

return [{
  json: {
    batch_id: batchId,
    correlation_id: item.correlation_id,
    idempotency_key: item.idempotency_key,
    conversation_id: item.conversation_id,
    company_id: item.company_id,
    user,
    files: fileItems
  }
}];

const item = $input.first().json;
const files = item.files || [];

function removeAccents(str) {
  return String(str || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd').replace(/Đ/g, 'D')
    .toLowerCase()
    .trim();
}

/**
 * Layer 1: Preliminary Filename-Based Classification
 * Executed BEFORE OCR (text is not yet available at this stage).
 * Accurately maps filename patterns to canonical document types.
 * Non-descriptive names (e.g. SWC00814.pdf) are assigned GENERAL pending Layer 2 content verification.
 */
function classifyByFilename(fileName) {
  const cleanFn = String(fileName || '').replace(/[\._\-]+/g, ' ');
  const f = removeAccents(cleanFn);

  if (/(?:can cuoc cong dan|cccd|vneid|dinh danh dien tu|cmnd|chung minh nhan dan|cuc canh sat quan ly hanh chinh|citizen|the can cuoc)/i.test(f)) {
    return 'CCCD_VNEID';
  }
  if (/(?:the bao hiem y te|bao hiem y te|bhyt|ma the bhyt|co quan bhxh|bao hiem xa hoi|health insurance)/i.test(f)) {
    return 'BHYT';
  }
  if (/(?:giay kham suc khoe|kham suc khoe|benh vien|ket luan suc khoe|phan loai suc khoe|\bksk\b|suc khoe|health check|medical)/i.test(f)) {
    return 'GIAY_KHAM_SUC_KHOE';
  }
  if (/(?:so yeu ly lich|ly lich ca nhan|ly lich tu thuat|thanh phan gia dinh|\bsyll\b)/i.test(f)) {
    return 'SO_YEU_LY_LICH';
  }
  if (/(?:don xin viec|don ung tuyen|phieu dang ky du tuyen|thu ung tuyen|\bcv\b|curriculum vitae|resume|ho so ung vien|job application)/i.test(f)) {
    return 'DON_XIN_VIEC';
  }
  if (/(?:quyet dinh tuyen dung|tiep nhan va bo tri|qd dsmn|bo nhiem|ve viec tiep nhan|quyet dinh ve viec|quyet dinh|\bqd\b|decision)/i.test(f)) {
    return 'QUYET_DINH_TUYEN_DUNG';
  }
  if (/(?:hop dong lao dong|\bhdld\b|phu luc hop dong|thoi han hop dong|nguoi su dung lao dong|hop dong|labor contract|employment contract)/i.test(f)) {
    return 'HOP_DONG_LAO_DONG';
  }
  if (/(?:bang tot nghiep|chung chi|giay chung nhan kha nang chuyen mon|thuyen truong|may truong|hang fc|chung chi chuyen mon|bang dai hoc|bang cao dang|bang cu nhan|bang ky su|certificate|degree|diploma)/i.test(f)) {
    return 'BANG_CAP_CHUNG_CHI';
  }
  if (/(?:bang thanh toan luong|bang luong|phieu luong|chuyen luong|don de nghi chuyen luong|salary|payroll)/i.test(f)) {
    return 'LUONG_PHU_CAP';
  }
  if (/(?:giay chung nhan ket hon|dang ky ket hon|tinh trang hon nhan|hon nhan|ket hon|marriage)/i.test(f)) {
    return 'GIAY_DANG_KY_KET_HON';
  }

  return 'GENERAL';
}

for (const f of files) {
  f.docType = classifyByFilename(f.fileName);
  f.classification_layer = 'LAYER_1_FILENAME';
}

const outputItems = [];
for (let i = 0; i < files.length; i++) {
  const f = files[i];
  outputItems.push({
    json: {
      fileIndex: i,
      totalFiles: files.length,
      fileName: f.fileName,
      docType: f.docType,
      classification_layer: f.classification_layer,
      binaryKey: f.binaryKey,
      fileSize: f.fileSize,
      mimeType: f.mimeType,
      fileStoragePath: f.fileStoragePath,
      batch_id: item.batch_id,
      correlation_id: item.correlation_id,
      idempotency_key: item.idempotency_key,
      conversation_id: item.conversation_id,
      company_id: item.company_id || null,
      user: item.user,
      gemini_parts: [
        {
          inline_data: {
            mime_type: f.mimeType,
            data: f.base64Data
          }
        },
        {
          text: 'Tài liệu: ' + f.fileName + ' (Phân loại sơ bộ: ' + f.docType + ')\nHãy bóc tách thông tin chi tiết của người lao động từ tài liệu này theo đúng 53 trường dữ liệu chuẩn của SOTRANS.'
        }
      ]
    }
  });
}

return outputItems;

