const ocrOutputs = $input.all();
const classifyOutputs = $('Classify - Document Type').all();
const prevData = classifyOutputs[0] ? classifyOutputs[0].json : {};

function removeAccents(str) {
  return String(str || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd').replace(/Đ/g, 'D')
    .toLowerCase()
    .trim();
}

/**
 * Layer 2: Content-Based Verification & Reclassification
 * Inspects actual OCR text extracted by Gemini to verify or upgrade Layer 1 classification.
 */
function classifyByContent(fileName, text) {
  const cleanFn = String(fileName || '').replace(/[\._\-]+/g, ' ');
  const combined = removeAccents(`${cleanFn} ${text || ''}`);

  if (/(?:can cuoc cong dan|cccd|vneid|dinh danh dien tu|cmnd|chung minh nhan dan|cuc canh sat quan ly hanh chinh|the can cuoc)/i.test(combined)) {
    return 'CCCD_VNEID';
  }
  if (/(?:the bao hiem y te|bao hiem y te|bhyt|ma the bhyt|co quan bhxh|bao hiem xa hoi)/i.test(combined)) {
    return 'BHYT';
  }
  if (/(?:giay kham suc khoe|kham suc khoe|benh vien|ket luan suc khoe|phan loai suc khoe|\bksk\b)/i.test(combined)) {
    return 'GIAY_KHAM_SUC_KHOE';
  }
  if (/(?:so yeu ly lich|ly lich ca nhan|ly lich tu thuat|thanh phan gia dinh)/i.test(combined)) {
    return 'SO_YEU_LY_LICH';
  }
  if (/(?:don xin viec|don ung tuyen|phieu dang ky du tuyen|thu ung tuyen|curriculum vitae|\bcv\b)/i.test(combined)) {
    return 'DON_XIN_VIEC';
  }
  if (/(?:quyet dinh tuyen dung|tiep nhan va bo tri|qd dsmn|bo nhiem|ve viec tiep nhan|quyet dinh ve viec|quyet dinh)/i.test(combined)) {
    return 'QUYET_DINH_TUYEN_DUNG';
  }
  if (/(?:hop dong lao dong|\bhdld\b|phu luc hop dong|thoi han hop dong|nguoi su dung lao dong)/i.test(combined)) {
    return 'HOP_DONG_LAO_DONG';
  }
  if (/(?:bang tot nghiep|chung chi|giay chung nhan kha nang chuyen mon|thuyen truong|may truong|hang fc|bang dai hoc|bang cao dang)/i.test(combined)) {
    return 'BANG_CAP_CHUNG_CHI';
  }
  if (/(?:bang thanh toan luong|bang luong|phieu luong|chuyen luong|don de nghi chuyen luong)/i.test(combined)) {
    return 'LUONG_PHU_CAP';
  }
  if (/(?:giay chung nhan ket hon|dang ky ket hon|tinh trang hon nhan)/i.test(combined)) {
    return 'GIAY_DANG_KY_KET_HON';
  }

  return 'GENERAL';
}

const processedFiles = [];

for (let i = 0; i < classifyOutputs.length; i++) {
  const f = classifyOutputs[i].json;
  const ocrRes = ocrOutputs[i] ? ocrOutputs[i].json : {};
  let extractedJson = {};
  let parseError = null;
  let rawText = '';

  try {
    if (ocrRes.candidates && ocrRes.candidates[0] && ocrRes.candidates[0].content) {
      const parts = ocrRes.candidates[0].content.parts || [];
      rawText = parts.map(p => p.text || '').join('').trim();
      const clean = rawText.replace(/^\`\`\`json\s*/i, '').replace(/\`\`\`\s*$/i, '').trim();
      if (clean) {
        extractedJson = JSON.parse(clean);
        if (Array.isArray(extractedJson)) {
          extractedJson = extractedJson[0] || {};
        }
      }
    } else if (ocrRes.error) {
      parseError = typeof ocrRes.error === 'string' ? ocrRes.error : (ocrRes.error.message || JSON.stringify(ocrRes.error));
      console.warn('[OCR Gemini Error] File: ' + f.fileName + ', CorrId: ' + (prevData.correlation_id || 'unknown') + ': ' + parseError);
    } else {
      parseError = 'No valid candidates returned from Gemini response';
      console.warn('[OCR Gemini Invalid Response] File: ' + f.fileName + ', CorrId: ' + (prevData.correlation_id || 'unknown'));
    }
  } catch (parseErr) {
    parseError = 'Lỗi phân tích JSON từ kết quả OCR: ' + parseErr.message;
    console.warn('[OCR Parse JSON Error] File: ' + f.fileName + ', CorrId: ' + (prevData.correlation_id || 'unknown') + ': ' + parseErr.message);
  }

  // Layer 2: Content-Based Verification / Reclassification
  let finalDocType = f.docType;
  let classificationLayer = f.classification_layer || 'LAYER_1_FILENAME';
  if (rawText && (f.docType === 'GENERAL' || f.docType === 'KHAC')) {
    const verifiedType = classifyByContent(f.fileName, rawText);
    if (verifiedType !== 'GENERAL') {
      finalDocType = verifiedType;
      classificationLayer = 'LAYER_2_CONTENT_VERIFIED';
    }
  }

  // Preserve provenance for each extracted field
  const provenance = {};
  if (extractedJson && typeof extractedJson === 'object') {
    for (const key of Object.keys(extractedJson)) {
      if (key.startsWith('_')) continue;
      const val = extractedJson[key];
      if (val !== null && val !== undefined && val !== '') {
        provenance[key] = {
          fileName: f.fileName,
          docType: finalDocType,
          binaryKey: f.binaryKey,
          value: val
        };
      }
    }
  }

  processedFiles.push({
    fileIndex: i,
    fileName: f.fileName,
    binaryKey: f.binaryKey,
    fileSize: f.fileSize,
    mimeType: f.mimeType,
    fileStoragePath: f.fileStoragePath,
    docType: finalDocType,
    classification_layer: classificationLayer,
    rawExtracted: extractedJson || {},
    provenance: provenance,
    ocrStatus: parseError ? 'failed' : 'success',
    ocrError: parseError,
    text: rawText // Pass extracted rawText to downstream Backend Normalizer
  });
}

// Check if ALL files failed OCR completely
const allOcrFailed = processedFiles.length > 0 && processedFiles.every(f => f.ocrStatus === 'failed');
const failureDetails = processedFiles.filter(f => f.ocrError).map(f => f.fileName + ': ' + f.ocrError).join('; ');

return [{
  json: {
    batch_id: prevData.batch_id,
    correlation_id: prevData.correlation_id,
    idempotency_key: prevData.idempotency_key,
    conversation_id: prevData.conversation_id,
    company_id: prevData.company_id || null,
    user: prevData.user,
    processed_files: processedFiles,
    all_ocr_failed: allOcrFailed,
    error: allOcrFailed ? ('Lỗi nhận diện OCR toàn bộ tài liệu: ' + failureDetails) : null,
    statusCode: allOcrFailed ? 502 : 200
  }
}];

